import{z as B,x as A,o as r,c as d,q as E,j as i,D as s,d as e,s as o,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Y-fast trie","description":"","frontmatter":{"title":"Y-fast trie","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/y-fast-trie.md","filePath":"cs/y-fast-trie.md","lastUpdated":1791063341000}'),f={name:"cs/y-fast-trie.md"};function p(m,a,g,D,T,h){const l=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=E('<h1 id="y-fast-trie" tabindex="-1">Y-fast trie <a class="header-anchor" href="#y-fast-trie" aria-label="Permalink to &quot;Y-fast trie&quot;">​</a></h1><div class="epigraph"><p>x-fast 用分层哈希存前缀；y-fast 把键分成 $\\Theta(\\log U)$ 大小的块，块代表进 x-fast，块内平衡树，空间回到 $O(n)$。</p><footer>—— 据 Willard, Log-Logarithmic Worst-Case Range Queries are Possible in Space $\\Theta(N)$, IPL 1983；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/van-emde-boas">上一课</a> 的 \\(O(\\log\\log U)\\) 漂亮，朴素空间随 \\(U\\) 涨。本课不重写 summary 簇。缺口是 Willard 的 y-fast trie：先理解 x-fast（每层前缀哈希 + 叶链表），再把连续 \\(\\Theta(w)\\) 个键收成代表，使哈希表项 \\(O(n)\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>x-fast trie：对每个已插入键的全部比特前缀建哈希，层 \\(i\\) 查 \\(x\\) 的 \\(i\\) 位前缀是否存在，二分深度得最长匹配，再跳到后继叶。时间 \\(O(\\log w)=O(\\log\\log U)\\)，空间 \\(O(n\\log U)\\)（每键 \\(w\\) 个前缀）。y-fast：叶层不存全部键，而存每块的最大（或代表）键，块内 BST 大小 \\(\\Theta(w)\\)。缺口是<strong>用一块代表换掉每键每层前缀</strong>，空间 \\(O(n)\\)，时间仍 \\(O(\\log\\log U)\\) 期望或最坏视哈希而定。</p><p><span class="marginnote">数字实例：取机器字 \\(w=64\\)、\\(n=100\\) 万个键。x-fast 每键存 64 层前缀哈希，约 6400 万项；y-fast 每约 64 个键只出 1 个代表，代表仅约 1.6 万个——哈希表项从 \\(n\\log U\\) 回到与 \\(n\\) 同阶。</span></p><p><span class="marginnote">Willard 1983, <em>Information Processing Letters</em>。哈希用动态完美或通用散列时，界随哈希合同走；本课不提前写下两课散列族。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找后继：在 x-fast 上找代表后继，再在相邻一两块的 BST 里比。插入删除：块过大则裂，过小则并，像 B 树但块大小跟 \\(w\\) 走。代表变则更新 x-fast 前缀。</p><p><span class="marginnote">直觉类比：x-fast 是图书馆薄薄的总索引卡，只登记每个书架的代表书；块内 BST 是书架上按序排好的书。查后继先翻索引锁定书架（贵结构只服务代表层），再在架上扫几步——索引薄了，整体依然快。</span></p>',10)),(r(),i(n,null,{default:s(()=>[o(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEYS%5B%22n%20%E4%B8%AA%E6%95%B4%E6%95%B0%E9%94%AE%22%5D%20--%3E%20BLK%5B%22%E5%9D%97%E5%A4%A7%E5%B0%8F%20%CE%98(w)%22%5D%0A%20%20BLK%20--%3E%20XF%5B%22%E4%BB%A3%E8%A1%A8%E9%94%AE%E7%9A%84%20x-fast%22%5D%0A%20%20BLK%20--%3E%20BST%5B%22%E5%9D%97%E5%86%85%E6%9C%89%E5%BA%8F%E6%A0%91%22%5D%0A%20%20XF%20--%3E%20SUCC%5B%22O(log%20log%20U)%20%E6%89%BE%E5%88%B0%E5%9D%97%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[e("与 vEB：y-fast 空间优；常数与哈希失败概率要写进合同。与平衡 BST：当 \\(n\\ll U\\) 且 \\(w\\) 固定，y-fast 渐近更好，实践常数常输给 "),t("a",{href:"/cs/treap"},"Treap"),e("。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"最长前缀匹配是比特 trie 的标准动作；哈希让「这一层有没有这个前缀」变期望 \\(O(1)\\)。块裂并摊还 \\(O(\\log\\log U)\\) 量级，分析类似 B 树加 x-fast 更新。",-1)),a[6]||(a[6]=t("p",null,[t("span",{class:"marginnote"},"常见误区：初学者容易以为块内也要再叠一层 x-fast。实际上块内就是普通平衡 BST——只有代表那层享受 \\(O(\\log\\log U)\\)，分块的意义正是让昂贵的结构只服务少量代表。")],-1)),(r(),i(n,null,{default:s(()=>[o(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%E6%96%B0%E9%94%AE%20x%22%5D%20--%3E%20LOC%7B%22x%20%E8%90%BD%E5%9C%A8%E5%93%AA%E4%B8%AA%E5%9D%97%22%7D%0A%20%20LOC%20--%3E%20PUT%5B%22%E5%9D%97%E5%86%85%20BST%20%E5%B8%B8%E8%A7%84%E6%8F%92%E5%85%A5%22%5D%0A%20%20PUT%20--%3E%20CHK%7B%22%E5%9D%97%E5%A4%A7%E5%B0%8F%E8%BF%98%E5%9C%A8%20%CE%98(w)%20%E5%86%85%E5%90%97%22%7D%0A%20%20CHK%20--%3E%20OK%5B%22%E6%98%AF%EF%BC%9A%E7%BB%93%E6%9D%9F%22%5D%0A%20%20CHK%20--%3E%20SPLIT%5B%22%E5%90%A6%EF%BC%9A%E8%A3%82%E6%88%90%E4%B8%A4%E4%B8%AA%E5%8D%8A%E5%9D%97%22%5D%0A%20%20SPLIT%20--%3E%20NEWREP%5B%22%E5%90%84%E9%80%89%E6%9C%80%E5%A4%A7%E9%94%AE%E5%BD%93%E6%96%B0%E4%BB%A3%E8%A1%A8%22%5D%0A%20%20NEWREP%20--%3E%20UPD%5B%22x-fast%20%E5%89%8D%E7%BC%80%E5%93%88%E5%B8%8C%E5%90%8C%E6%AD%A5%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p>不要把本课写成 IP 路由硬件——那是最长前缀的应用，机制已够。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入融合树。几何区间 stabbing 不是整数后继：下一课区间树，键是线段端点。</p><p>后课默认：整数宇宙后继可用 y-fast 换空间。轴对齐区间的stabbing 用区间树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>x-fast：\\(O(n w)\\) 空间，\\(O(\\log\\log U)\\) 后继。</li><li>y-fast：分块代表，空间 \\(O(n)\\)。</li><li>下一课从一维整数换到区间几何。</li><li>出处：Willard, <em>IPL</em>, 1983；Cormen et al.。</li></ul>',6))])}const C=B(f,[["render",p]]);export{u as __pageData,C as default};
